def proposal(form, language):
    for field in form.fields.values():
        field.label = caption(field.label, language)
        field.help_text = caption(field.help_text, language)
        # Model-backed choices retain their own labels, querysets and lazy evaluation.
        if hasattr(field, "choices") and not hasattr(field, "queryset"):
            field.choices = [(value, caption(label, language)) for value, label in field.choices]
    form.fields["operation"].label = "Operation" if language == "en" else "Operación"

def validate(value):
    if not isinstance(value, dict) or (set(value) != set(FIELDS) and set(value) != LEGACY_FIELDS):
        raise ValidationError("Complete profile details required / Detalles completos obligatorios")
    flags = ["reception", "travel"] + (["show_trans_label"] if "show_trans_label" in value else [])
    if any(type(value[field]) is not bool for field in flags):
        raise ValidationError("Invalid detail flags / Opciones no válidas")
    for field, limit in [("spoken_languages", 6), ("days", 7), ("travel_areas", 1000)]:
        items = value[field]
        if not isinstance(items, list) or len(items) > limit:
            raise ValidationError("Invalid detail list / Lista de detalles no válida")
        if field == "travel_areas":
            if any(type(pk) is not int or not 0 < pk <= 9223372036854775807 for pk in items):
                raise ValidationError("Invalid travel city / Ciudad de desplazamiento no válida")
        elif any(not isinstance(item, str) for item in items):
            raise ValidationError("Invalid detail choice / Opción de detalles no válida")
        if len(set(items)) != len(items):
            raise ValidationError("Duplicate detail choices / Opciones duplicadas")
    if any(
        not isinstance(value[field], str)
        for field in ["content_language", "profile_type", "time_slot"]
    ):
        raise ValidationError("Invalid detail choice / Opción de detalles no válida")
    editor = Editor(value)
    if not editor.is_valid():
        raise ValidationError("Invalid profile details / Detalles de perfil no válidos")
    cities = Municipality.objects.filter(pk__in=value["travel_areas"], active=True).order_by("pk")
    if connection.in_atomic_block:
        cities = cities.select_for_update()
    if len(list(cities)) != len(value["travel_areas"]):
        raise ValidationError("Travel city unavailable / Ciudad de desplazamiento no disponible")
    return {
        **{field: editor.cleaned_data[field] for field in SCALARS if field in value},
        "spoken_languages": sorted(value["spoken_languages"]),
        "days": sorted(value["days"]),
        "travel_areas": sorted(value["travel_areas"]),
    }

def validate(value, person=None):
    if (
        not isinstance(value, dict)
        or set(value) != {"phone", "whatsapp", "telegram"}
        or not isinstance(value["phone"], str)
        or len(value["phone"]) > 30
        or type(value["whatsapp"]) is not bool
        or not isinstance(value["telegram"], str)
        or len(value["telegram"]) > 32
    ):
        raise ValidationError("Invalid contact fields / Campos de contacto no válidos")
    normalized = {
        "phone": normalize_phone(value["phone"]) if value["phone"] else "",
        "whatsapp": value["whatsapp"],
        "telegram": normalize_telegram(value["telegram"]),
    }
    if normalized["whatsapp"] and not normalized["phone"]:
        raise ValidationError("WhatsApp requires a phone / WhatsApp requiere teléfono")
    if person is not None:
        claim(normalized, person)
    return normalized

def validate(value):
    if not isinstance(value, dict) or set(value) != {"municipality", "postal_code", "zone"}:
        raise ValidationError("Complete location required / Ubicación completa obligatoria")
    rows = {}
    for field, model in [
        ("municipality", Municipality),
        ("postal_code", PostalCode),
        ("zone", Zone),
    ]:
        identifier = value[field]
        if identifier is None and field != "municipality":
            rows[field] = None
            continue
        if type(identifier) is not int or not 0 < identifier <= 9223372036854775807:
            raise ValidationError("Invalid location reference / Referencia geográfica no válida")
        query = model.objects.all()
        if connection.in_atomic_block:
            query = query.select_for_update()
        row = query.filter(pk=identifier).first()
        if not row or (field != "postal_code" and not row.active):
            raise ValidationError("Location unavailable / Ubicación no disponible")
        rows[field] = row
    city, postal, zone = rows["municipality"], rows["postal_code"], rows["zone"]
    if postal and (not postal.public_safe or not postal.municipalities.filter(pk=city.pk).exists()):
        raise ValidationError(
            "Postal code incompatible or restricted / CP incompatible o restringido"
        )
    if zone and zone.municipality_id != city.pk:
        raise ValidationError("Area does not match city / Zona incompatible con ciudad")
    return value

def validate(value):
    if not isinstance(value, dict) or set(value) != {"categories", "services"}:
        raise ValidationError(
            "Complete catalog selection required / Selección completa obligatoria"
        )
    rows = {}
    normalized = {}
    for field, model, limit in [("categories", Category, 100), ("services", Service, 500)]:
        identifiers = value[field]
        if (
            not isinstance(identifiers, list)
            or not 1 <= len(identifiers) <= limit
            or any(type(pk) is not int or not 0 < pk <= 9223372036854775807 for pk in identifiers)
            or len(set(identifiers)) != len(identifiers)
        ):
            raise ValidationError("Invalid catalog selection / Selección de catálogo no válida")
        normalized[field] = sorted(identifiers)
        query = model.objects.filter(pk__in=identifiers, active=True).order_by("pk")
        if connection.in_atomic_block:
            query = query.select_for_update()
        rows[field] = list(query)
        if len(rows[field]) != len(identifiers):
            raise ValidationError("Catalog selection unavailable / Selección no disponible")
    if any(service.category_id not in normalized["categories"] for service in rows["services"]):
        raise ValidationError("Service outside selected categories / Servicio fuera de categorías")
    return normalized

