@sensitive_variables()
def capture(label, purpose, queryset, fields):
    model = queryset.model
    queryset = model.objects.filter(pk__in=queryset.values('pk'))
    excluded = Q()
    for path in current_case_paths(model._meta.label):
        excluded |= Q(**{path: case.pk})
    if excluded:
        queryset = queryset.exclude(excluded)
    names = [field.attname for field in model._meta.concrete_fields]
    rows = list(queryset.select_for_update(of=('self',)).order_by('pk').values(*names))
    records = []
    for row in rows:
        reference = fingerprint(canonical({'model': label, 'pk': normalized(row[model._meta.pk.attname])}))
        facts = {field.attname: {'digest': fingerprint(canonical(normalized(row[field.attname]))), 'type': field.get_internal_type()} for field in model._meta.concrete_fields}
        records.append({'reference': reference, 'fields': facts})
        if value_sink is not None:
            value_sink(label, reference, row)
    entries.append({'model': label, 'purpose': purpose, 'count': len(records), 'fields': {field.attname: field.get_internal_type() for field in model._meta.concrete_fields}, 'records': records, 'digest': fingerprint(canonical(records))})
    return rows

